import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { parseWorkbook } from "../parse";
import { parsePdf } from "../pdf";
import { readCostumeWorkbook, type ClassSheet } from "../workbook";

/**
 * Generated by scripts/make-sample-workbook.ts in the layout studios send: a
 * summary tab, then one tab per class with the costume written above the table.
 */
const XLSX_PATH = "sample-data/holiday-costume-workbook.xlsx";
const PDF_PATH = "sample-data/holiday-costume-workbook.pdf";

const byTab = (classes: ClassSheet[], tab: string) => {
  const found = classes.find((c) => c.sheetName === tab);
  if (!found) throw new Error(`no tab ${tab}`);
  return found;
};

describe("readCostumeWorkbook", () => {
  const classes = readCostumeWorkbook(parseWorkbook(readFileSync(XLSX_PATH)));

  it("finds a class per tab and ignores the summary", () => {
    expect(classes.map((c) => [c.sheetName, c.kind])).toEqual([
      ["Summary", "other"],
      ["Jingle Hop - Ms Ana 3-4", "class"],
      ["Snow Day - Mr Lee 5-6", "class"],
      ["Musical Theater - Weiss", "class"],
      ["Intermediate - Ms Kay", "class"],
    ]);
  });

  it("reads each class's costume from its own tab", () => {
    expect(byTab(classes, "Jingle Hop - Ms Ana 3-4").costume).toMatchObject({
      status: "selected",
      companySlug: "awishcometrue",
      pieces: ["10096Y"],
      alternate: { pieces: ["16179G"] },
    });
    expect(byTab(classes, "Musical Theater - Weiss").costume).toMatchObject({
      companySlug: "weissman",
      pieces: ["19544"],
    });
    expect(byTab(classes, "Snow Day - Mr Lee 5-6").costume.status).toBe("not-selected");
  });

  it("names the class from the title line and finds the blank Size column", () => {
    const cls = byTab(classes, "Jingle Hop - Ms Ana 3-4");
    expect(cls.className).toBe("Jingle Hop (Sample Song) — Ballet");
    expect(cls.headers[cls.sizeColumn!]).toBe("Size");
  });

  it("drops the footnote under the table instead of reading it as a dancer", () => {
    const cls = byTab(classes, "Jingle Hop - Ms Ana 3-4");
    expect(cls.dancers).toHaveLength(6);
    expect(cls.dancers.every((d) => d.name.length > 0)).toBe(true);
  });

  it("carries the sheet's own note for a dancer who was not measured", () => {
    const d = byTab(classes, "Jingle Hop - Ms Ana 3-4").dancers.find((x) =>
      x.name.startsWith("Clementine"),
    )!;
    expect(d.girth).toBeUndefined();
    expect(d.issues[0].message).toContain("Measurements not taken yet");
  });

  it("warns when Excel has turned a name into a date", () => {
    const d = byTab(classes, "Snow Day - Mr Lee 5-6").dancers[1];
    expect(d.name).toBe("2026-06-01 Brightwater");
    expect(d.girth).toBe(46);
    expect(d.issues.some((i) => /reads as a date/.test(i.message))).toBe(true);
  });

  it("flags the same dancer measured differently on two tabs", () => {
    const mt = byTab(classes, "Musical Theater - Weiss").dancers.find((d) =>
      d.name.startsWith("Saoirse"),
    )!;
    const inter = byTab(classes, "Intermediate - Ms Kay").dancers.find((d) =>
      d.name.startsWith("Saoirse"),
    )!;
    expect(mt.issues.map((i) => i.message).join()).toMatch(/Inseam is 36 here but 26/);
    expect(inter.issues.map((i) => i.message).join()).toMatch(/Inseam is 26 here but 36/);
  });
});

describe("parsePdf", () => {
  it("reads a PDF of the workbook exactly as it reads the spreadsheet", async () => {
    const fromPdf = readCostumeWorkbook(await parsePdf(readFileSync(PDF_PATH)));
    const fromXlsx = readCostumeWorkbook(parseWorkbook(readFileSync(XLSX_PATH)));

    const essentials = (classes: ClassSheet[]) =>
      classes.map((c) => ({
        tab: c.sheetName,
        kind: c.kind,
        className: c.className,
        costume: c.costume,
        sizeHeader: c.sizeColumn === null ? null : c.headers[c.sizeColumn],
        dancers:
          c.kind === "class"
            ? c.dancers.map((d) => ({
                name: d.name,
                girth: d.girth,
                bust: d.bust,
                waist: d.waist,
                hips: d.hips,
                inseam: d.inseam,
                height: d.height,
                notes: d.notes,
                issues: d.issues.map((i) => i.message),
              }))
            : [],
      }));

    expect(essentials(fromPdf)).toEqual(essentials(fromXlsx));
  });

  it("rejects a PDF with no text, rather than guessing", async () => {
    // A minimal one-page PDF with no text on it, as a scan would be.
    const blank = [
      "%PDF-1.4",
      "1 0 obj<</Type/Catalog/Pages 2 0 R>>endobj",
      "2 0 obj<</Type/Pages/Kids[3 0 R]/Count 1>>endobj",
      "3 0 obj<</Type/Page/Parent 2 0 R/MediaBox[0 0 200 200]>>endobj",
      "trailer<</Root 1 0 R>>",
      "%%EOF",
    ].join("\n");
    await expect(parsePdf(Buffer.from(blank))).rejects.toThrow(/scan or a photo/);
  });
});
